// Define the schema for Sampler integration
const samplerIntegrationSchema = {
  type: 'object',
  properties: {
    samplerId: { type: 'string' },
    sampleData: { type: 'array', items: { type: 'number' } }
  },
  required: ['samplerId', 'sampleData']
};

module.exports = samplerIntegrationSchema;

import samplerIntegrationSchema from '../src/sampler_integration_contract.mjs';

const assert = require('assert');

const validSamplerData = {
  samplerId: 'sampler123',
  sampleData: [1.0, 2.0, 3.0]
};

const invalidSamplerData = {
  samplerId: 'sampler123',
  sampleData: 'not an array'
};

const testSuite = {
  'Valid sampler data should pass validation': () => {
    assert.deepStrictEqual(samplerIntegrationSchema.validate(validSamplerData), validSamplerData);
  },
  'Invalid sampler data should fail validation': () => {
    assert.throws(() => samplerIntegrationSchema.validate(invalidSamplerData));
  }
};

module.exports = testSuite;

